// PV6 activity: what the index records for each write, and who may read it. Over the real router, index core,
// pipeline, policy engine and SQLite D1. Fixtures are generated bytes, never real files.

import { randomBytes } from "node:crypto";
import { FakeDigestStream, World, sha256hex, type User } from "./harness.js";

beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});
afterAll(() => {
  delete (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream;
});

describe("activity", () => {
  let w: World;
  let A: { id: string; pub: string };
  let owner: User, editor: User, viewer: User, guest: User;
  let base: string;

  beforeEach(async () => {
    w = new World();
    A = w.newOrg();
    owner = w.newUser("owner");
    editor = w.newUser("editor");
    viewer = w.newUser("viewer");
    guest = w.newUser("guest");
    w.grant(A, owner, "owner");
    w.grant(A, editor, "builder");
    w.grant(A, viewer, "viewer");
    const lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Log" })).json.data.library;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    await w.call(owner, "PUT", `${base}/members/${editor.id}`, { role: "editor" });
    await w.call(owner, "PUT", `${base}/members/${viewer.id}`, { role: "viewer" });
    await w.call(owner, "POST", `${base}/invitations`, { email: guest.email, role: "uploader" });
    await w.call(guest, "POST", "/v1/media/invitations/accept");
  });

  async function upload(user: User, name: string, extra: Record<string, unknown> = {}) {
    const bytes = randomBytes(100);
    const s = (await w.call(user, "POST", `${base}/uploads`, { name, size: bytes.length, sha256: sha256hex(bytes), mime: "application/octet-stream", ...extra })).json.data.session;
    await w.put(user, `${base}/uploads/${s.id}/parts/1`, bytes);
    return (await w.call(user, "POST", `${base}/uploads/${s.id}/commit`)).json.data.file;
  }
  const log = async (user: User, q = "") => (await w.call(user, "GET", `${base}/activity${q}`)).json?.data?.activity as { actor: string; op: string; fileId: string | null; detail: Record<string, unknown> }[];

  it("records who did what to which file, newest first, with names and states but no contents or words", async () => {
    const f = await upload(editor, "plan.bin", { visibility: "public" });
    await w.runPipelines();
    await w.call(editor, "PATCH", `${base}/files/${f.id}`, { folder: "/docs" });
    await w.call(viewer, "POST", `${base}/files/${f.id}/comments`, { body: "secret words here" });
    await w.call(editor, "DELETE", `${base}/files/${f.id}`);
    await w.call(owner, "POST", `${base}/files/${f.id}/restore`);
    const entries = await log(viewer);
    expect(entries.map((e) => `${e.op}:${e.actor}`)).toEqual([
      `file.restored:${owner.id}`,
      `file.trashed:${editor.id}`,
      `file.commented:${viewer.id}`,
      `file.moved:${editor.id}`,
      "file.processed:pipeline",
      `file.uploaded:${editor.id}`,
    ]);
    expect(entries.find((e) => e.op === "file.moved")!.detail).toMatchObject({ name: "plan.bin", to: "/docs/plan.bin" });
    expect(entries.find((e) => e.op === "file.processed")!.detail).toMatchObject({ status: "public" });
    expect(entries.every((e) => e.fileId === f.id)).toBe(true);
    expect(JSON.stringify(entries)).not.toContain("secret words");
  });

  it("one file's log follows the file's access; the library's needs file.list", async () => {
    const theirs = await upload(editor, "theirs.bin");
    const mine = await upload(guest, "mine.bin");
    expect((await log(guest, `?file=${mine.id}`)).map((e) => e.op)).toEqual(["file.uploaded"]);
    expect((await w.call(guest, "GET", `${base}/activity?file=${theirs.id}`)).status).toBe(404);
    expect((await w.call(guest, "GET", `${base}/activity`)).status).toBe(404);
    expect((await log(viewer, `?file=${theirs.id}`)).map((e) => e.op)).toEqual(["file.uploaded"]);
    expect((await w.call(viewer, "GET", `${base}/activity?cursor=abc`)).status).toBe(422);
  });

  it("an operator's takedown shows as \"operator\"; batches record one entry per file; pages follow the cursor", async () => {
    const a = await upload(editor, "a.bin");
    const b = await upload(editor, "b.bin");
    const core = [...w.index.cores.values()][0]!;
    const { dispatchAndRecord } = await import("@media-worker/index-do/library-index");
    // Through the router as a batch:
    await w.call(editor, "POST", `${base}/files:batch`, { action: "move", ids: [a.id, b.id], folder: "/sorted" });
    const moves = (await log(viewer)).filter((e) => e.op === "file.moved");
    expect(moves).toHaveLength(2);
    expect(moves.every((e) => e.detail.batch === true && e.detail.to === "/sorted")).toBe(true);

    // A takedown, as the operator routes call the index (with the operator's id as actor):
    const id = a.id.slice(4).replace(/(.{8})(.{4})(.{4})(.{4})(.{12})/, "$1-$2-$3-$4-$5");
    const libraryId = [...w.index.cores.keys()][0]!.split(":lib:")[1]!;
    const r = dispatchAndRecord(core, { orgId: A.id, libraryId, actor: "usr_0123456789abcdef0123456789abcdef" }, { op: "takedown", id, note: "t", nowIso: new Date().toISOString() } as never);
    expect(r.ok).toBe(true);
    const top = (await log(viewer))[0]!;
    expect(top).toMatchObject({ op: "file.taken_down", actor: "operator" });

    const page1 = (await w.call(viewer, "GET", `${base}/activity?limit=2`)).json.data;
    expect(page1.activity).toHaveLength(2);
    const page2 = (await w.call(viewer, "GET", `${base}/activity?limit=2&cursor=${page1.nextCursor}`)).json.data;
    expect(page2.activity[0].id).toBeLessThan(page1.activity[1].id);
  });
});
